using sv_69e1edef02f64c0e86e1d387842bbe1f.Models;

namespace sv_69e1edef02f64c0e86e1d387842bbe1f.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

using sv_69e1edef02f64c0e86e1d387842bbe1f.Models;

namespace sv_69e1edef02f64c0e86e1d387842bbe1f.Services;

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> SeedData = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic Neapolitan pizza with fresh mozzarella, basil, and San Marzano tomatoes.", 30),
            new(2, "Spaghetti Carbonara", "Creamy pasta with guanciale, Pecorino Romano, and black pepper.", 25),
            new(3, "Risotto alla Milanese", "Saffron-infused Arborio rice cooked slowly in broth with Parmesan.", 45),
        },
        [2] = new List<Recipe>
        {
            new(4, "Chicken Tikka Masala", "Tender chicken pieces in a rich, spiced tomato-cream sauce.", 50),
            new(5, "Palak Paneer", "Fresh spinach curry with cubes of soft paneer cheese.", 35),
            new(6, "Biryani", "Fragrant basmati rice layered with spiced meat and caramelized onions.", 60),
        },
        [3] = new List<Recipe>
        {
            new(7, "Tacos al Pastor", "Marinated pork tacos with pineapple, cilantro, and onion.", 40),
            new(8, "Guacamole", "Fresh avocado dip with lime, cilantro, jalapeño, and tomato.", 10),
            new(9, "Enchiladas Verdes", "Corn tortillas filled with chicken and topped with tangy green salsa.", 45),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (SeedData.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_69e1edef02f64c0e86e1d387842bbe1f.Models
@using sv_69e1edef02f64c0e86e1d387842bbe1f.Services
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h1>Recipes — Cuisine @CuisineId</h1>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}

@if (_recipes is null && _isLoading)
{
    <p><em>Loading recipes…</em></p>
}
else if (_recipes is not null)
{
    @if (_isLoading)
    {
        <p><em>Refreshing…</em></p>
    }

    <table class="table">
        <thead>
            <tr>
                <th>Title</th>
                <th>Description</th>
                <th>Prep Time (min)</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var recipe in DisplayedRecipes)
            {
                <tr>
                    <td>@recipe.Title</td>
                    <td>@recipe.Description</td>
                    <td>@recipe.PrepTimeMinutes</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isLoading;
    private string? _errorMessage;
    private int _loadedCuisineId;
    private CancellationTokenSource? _loadCts;

    private IEnumerable<Recipe> DisplayedRecipes =>
        string.Equals(Sort, "newest", StringComparison.OrdinalIgnoreCase)
            ? _recipes!.OrderByDescending(r => r.Id)
            : string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
                ? _recipes!.OrderBy(r => r.PrepTimeMinutes)
                : _recipes!;

    protected override Task OnInitializedAsync()
    {
        Navigation.LocationChanged += OnLocationChanged;
        return LoadRecipesAsync();
    }

    public override Task SetParametersAsync(ParameterView parameters)
    {
        // Capture old CuisineId before the base class updates it.
        var previousCuisineId = CuisineId;
        var result = base.SetParametersAsync(parameters);

        // After first render, cuisine changes are handled by OnLocationChanged.
        // Sort-only changes need no reload — DisplayedRecipes recomputes automatically.
        return result;
    }

    private void OnLocationChanged(object? sender, Microsoft.AspNetCore.Components.Routing.LocationChangedEventArgs e)
    {
        // Parse the new CuisineId from the URL to detect cuisine-only changes.
        // Sort changes are handled purely by re-rendering (DisplayedRecipes recomputes).
        var uri = new Uri(e.Location);
        var segments = uri.AbsolutePath.Trim('/').Split('/');
        if (segments.Length >= 2
            && string.Equals(segments[0], "recipes", StringComparison.OrdinalIgnoreCase)
            && int.TryParse(segments[1], out var newCuisineId)
            && newCuisineId != _loadedCuisineId)
        {
            CuisineId = newCuisineId;
            _ = LoadRecipesAsync();
        }
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load.
        _loadCts?.Cancel();
        _loadCts?.Dispose();
        _loadCts = new CancellationTokenSource();
        var cts = _loadCts;

        _isLoading = true;
        _errorMessage = null;
        _loadedCuisineId = CuisineId;
        StateHasChanged();

        try
        {
            var recipes = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);

            if (cts.Token.IsCancellationRequested)
                return;

            _recipes = recipes;
            _isLoading = false;
        }
        catch (OperationCanceledException)
        {
            // Load was superseded or component disposed — do nothing.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _isLoading = false;
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _isLoading = false;
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            if (!cts.Token.IsCancellationRequested)
            {
                StateHasChanged();
            }
        }
    }

    private Task RetryAsync() => LoadRecipesAsync();

    public void Dispose()
    {
        Navigation.LocationChanged -= OnLocationChanged;
        _loadCts?.Cancel();
        _loadCts?.Dispose();
    }
}

